    /// <summary>所有常量张量的 float32 数据（按 WeightOff 索引）。</summary>
    public static readonly float[] WeightData = DecodeWeights();

    private static float[] DecodeWeights()
    {
        var bytes = Convert.FromBase64String(WeightB64);
        var f = new float[bytes.Length / 4];
        Buffer.BlockCopy(bytes, 0, f, 0, bytes.Length);
        return f;
    }
